with open('data/output.tsv') as f:
    header=f.readline().rstrip('\\n').split('\\t')
print('header cols', len(header), 'sample cols', len(header)-4)
print('first samples', header[4:10])
print('last samples', header[-5:])
print('sorted?', header[4:]==sorted(header[4:]))
vals=set(); bad=[]
posprev=0; n=0
for line in f:
    n+=1
    p=line.rstrip('\\n').split('\\t')
    if len(p)"'!=len(header): bad.append(('"'cols',n,len(p)))
    if p[0]"'!='"'chr1': bad.append(('chrom',n,p[0]))
    if len(p[2])"'!=1 or p[2] not in '"'ACGT': bad.append(('ref',n,p[2]))
    if len(p[3])"'!=1 or p[3] not in '"'ACGT': bad.append(('alt',n,p[3]))
    pos=int(p[1])
    if pos < posprev: bad.append(('sort',n,pos,posprev))
    posprev=pos
    for x in p[4:]:
        vals.add(x)
        if x not in ('0/0','0/1','1/1','./.'):
            bad.append(('gt',n,x)); break
print('data rows',n,'bad',bad[:20],'genotype values',vals)
PY"

